package emon;


public final class Pageunittest {
    public static int planOf(emon.Port.Cells pl, int pages, int kind) {
        // `pages` rows; every page of `kind`, with a stream at bytes 100 + 50 of the input, a box and a page size.
        int i = 0;
        while (i < pages) {
            emon.Port.cellsPush(pl, kind);
            emon.Port.cellsPush(pl, 9);
            emon.Port.cellsPush(pl, 100);
            emon.Port.cellsPush(pl, 50);
            emon.Port.cellsPush(pl, 0);
            emon.Port.cellsPush(pl, 0);
            emon.Port.cellsPush(pl, 61200);
            emon.Port.cellsPush(pl, 79200);
            emon.Port.cellsPush(pl, 61200);
            emon.Port.cellsPush(pl, 79200);
            i += 1;
        }
        return 0;
    }
    public static int runPage(int i, int policy, emon.Port.Cells pl, emon.Port.Cells ans, emon.Port.Cells rq) {
        return Pageunit.puRunPdf(i, 3, policy, pl, ans, rq, emon.Port.newCells(), emon.Port.newBitmapSet(), emon.Port.newCells(), emon.Port.newCells(), emon.Port.newCells(), emon.Port.newCells(), emon.Port.newCells(), emon.Port.newCells(), emon.Port.newCells(), emon.Port.newCells(), emon.Port.newCells(), emon.Port.newCells(), emon.Port.newCells(), emon.Port.newCells(), emon.Port.newCells(), emon.Port.newCells(), emon.Port.newCells());
    }
    public static void testIdsArePerPageUnit() {
        emon.Testport.assertEq(Plan.puId(0, Plan.piDecode()), 260, "page 0 decode");
        emon.Testport.assertEq(Plan.puId(0, Plan.piRenderText()), 257, "page 0 render with text");
        emon.Testport.assertEq(Plan.puId(41, Plan.piDecode()), 10756, "page 41 decode: 42 * 256 + 4");
        emon.Testport.assertEq(Plan.puViewId(0, 1), Plan.viewBase() + 1, "a kin-made view of page 0");
        emon.Testport.assertEq(Plan.puViewId(2, 5), Plan.viewBase() + 517, "and of page 2");
        emon.Testport.assertThat(Plan.viewBase() > Plan.puId(60000, 255), "no request id reaches the views' range");
    }
    public static void testAScannedPagesUnitAsksForItsStreamUnderItsOwnId() {
        emon.Port.Cells pl = emon.Port.newCells();
        emon.Port.Cells rq = emon.Port.newCells();
        planOf(pl, 3, Pageunit.pkScan());
        emon.Testport.assertEq(runPage(1, 2, pl, emon.Port.newCells(), rq), Plan.usRequests(), "it asks");
        emon.Testport.assertEq(Plan.recKind(rq, 0), Plan.pkDecode(), "a decode");
        emon.Testport.assertEq(Plan.recId(rq, 0), 516, "page 1: 2 * 256 + 4");
        emon.Testport.assertEq(Plan.rqArg(rq, 0, 0), 3, "of input 3");
        emon.Testport.assertEq(Plan.rqArg(rq, 0, 1), 100, "the stream's start");
        emon.Testport.assertEq(Plan.rqArg(rq, 0, 2), 50, "and length");
        emon.Testport.assertEq(Plan.rqArg(rq, 0, 3), Plan.fltDct(), "a DCT stream");
    }
    public static void testAUnitWithNoAnswersAsksTheSameEveryTime() {
        emon.Port.Cells pl = emon.Port.newCells();
        emon.Port.Cells rq1 = emon.Port.newCells();
        emon.Port.Cells rq2 = emon.Port.newCells();
        planOf(pl, 2, Pageunit.pkScan());
        runPage(0, 2, pl, emon.Port.newCells(), rq1);
        runPage(0, 2, pl, emon.Port.newCells(), rq2);
        emon.Testport.assertEq(emon.Port.cellsLen(rq1), emon.Port.cellsLen(rq2), "the same length");
        emon.Testport.assertEq(emon.Port.cellsAt(rq1, 2), emon.Port.cellsAt(rq2, 2), "the same id");
        emon.Testport.assertEq(emon.Port.cellsAt(rq1, 4), emon.Port.cellsAt(rq2, 4), "the same arguments");
    }
    public static void testABornDigitalPageAndTheNeverPolicyAskNothing() {
        emon.Port.Cells pl = emon.Port.newCells();
        emon.Port.Cells rq = emon.Port.newCells();
        planOf(pl, 1, Pageunit.pkBorn());
        emon.Testport.assertEq(runPage(0, 2, pl, emon.Port.newCells(), rq), Plan.usDone(), "born digital: done");
        emon.Testport.assertEq(emon.Port.cellsLen(rq), 0, "no request");
        emon.Port.Cells plan2 = emon.Port.newCells();
        emon.Port.Cells rq2 = emon.Port.newCells();
        planOf(plan2, 1, Pageunit.pkScan());
        emon.Testport.assertEq(runPage(0, 0, plan2, emon.Port.newCells(), rq2), Plan.usDone(), "never: done");
        emon.Testport.assertEq(emon.Port.cellsLen(rq2), 0, "no request");
        emon.Port.Cells plan3 = emon.Port.newCells();
        emon.Port.Cells rq3 = emon.Port.newCells();
        planOf(plan3, 1, Pageunit.pkNone());
        emon.Testport.assertEq(runPage(0, 2, plan3, emon.Port.newCells(), rq3), Plan.usDone(), "no image: done");
        emon.Testport.assertEq(emon.Port.cellsLen(rq3), 0, "no request");
    }
    public static void testTheBitmapSetKeepsWhatKinMakes() {
        emon.Port.BitmapSet s = emon.Port.newBitmapSet();
        emon.Testport.assertEq(emon.Port.bmsHas(s, 5), 0, "empty");
        emon.Testport.assertEq(emon.Port.bitmapW(emon.Port.bmsGet(s, 5)), 0, "an absent bitmap is 0 x 0");
        emon.Testport.assertEq(emon.Port.bitmapH(emon.Port.bmsGet(s, 5)), 0, "in both directions");
        emon.Port.Bitmap b = emon.Port.bmsPut(s, Plan.viewBase(), 4, 3, 1);
        emon.Testport.assertEq(emon.Port.bmsHas(s, Plan.viewBase()), 1, "put");
        emon.Testport.assertEq(emon.Port.bitmapW(b), 4, "its width");
        emon.Testport.assertEq(emon.Port.bitmapH(b), 3, "its height");
        emon.Testport.assertEq(emon.Port.bitmapChannels(b), 1, "its channels");
        emon.Testport.assertEq(emon.Port.bitmapU8(b, 1, 1, 0), 0, "zeroed");
        emon.Port.bitmapSetU8(b, 1, 1, 0, 200);
        emon.Testport.assertEq(emon.Port.bitmapU8(emon.Port.bmsGet(s, Plan.viewBase()), 1, 1, 0), 200, "the set holds the very bitmap kin filled");
        emon.Testport.assertEq(emon.Port.bmsHas(s, Plan.viewBase() + 1), 0, "another id is absent");
    }
}
